// Read the form, clean it up, and decide whether the meeting can be processed at all.
const j = $input.first().json;
const title = String(j['Meeting title'] ?? '').trim();
const meetingDate = String(j['Meeting date'] ?? '').trim();
const transcript = String(j['Transcript'] ?? '').replace(/\r\n/g, '\n').trim();
const attendees = String(j['Attendees'] ?? '').split(/[\n,;、，]+/).map((s) => s.trim()).filter(Boolean);

// a short stable id from title + date + transcript, so the same meeting is never minuted twice (cyrb53 hash)
function hash(str) {
  let h1 = 0xdeadbeef, h2 = 0x41c6ce57;
  for (let i = 0; i < str.length; i++) {
    const c = str.charCodeAt(i);
    h1 = Math.imul(h1 ^ c, 2654435761);
    h2 = Math.imul(h2 ^ c, 1597334677);
  }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  return (4294967296 * (2097151 & h2) + (h1 >>> 0)).toString(36);
}
const meetingId = 'mt-' + hash(title + '|' + meetingDate + '|' + transcript);

let skip = '';
const realDate = /^\d{4}-\d{2}-\d{2}$/.test(meetingDate) && !isNaN(new Date(meetingDate + 'T00:00:00Z').getTime());
if (!title) skip = 'the meeting title is empty';
else if (!realDate) skip = 'the meeting date is not a valid date (use yyyy-MM-dd)';
else if (transcript.length < Number(j.min_transcript_chars)) skip = 'the transcript is shorter than ' + j.min_transcript_chars + ' characters';
else if (transcript.length > Number(j.max_transcript_chars)) skip = 'the transcript is longer than ' + j.max_transcript_chars + ' characters (split the meeting)';

return [{ json: { meeting_id: meetingId, title, meeting_date: meetingDate, attendees, attendees_text: attendees.join(', '), transcript,
  output_language: j.output_language, min_quote_chars: j.min_quote_chars, now: $now.toISO(), skip_reason: skip } }];

// The Minutes tab is the record of what has been done. A meeting that is already there is skipped.
const m = $('Prepare meeting').first().json;
const done = new Set($input.all().map((i) => String(i.json.meeting_id ?? '')).filter(Boolean));
const skip = m.skip_reason || (done.has(m.meeting_id) ? 'it is already in the Minutes tab (same title, date and transcript)' : '');
return [{ json: { ...m, skip_reason: skip } }];

// ---- guard for AI-written meeting minutes -------------------------------------------------
// Everything below is plain code. The AI proposes; this code checks each claim against the transcript.
const nfkc = (s) => String(s ?? '').normalize('NFKC');
// same text for comparing: width-normalized, lower case, curly quotes / dashes unified
const norm = (s) => nfkc(s).replace(/[‘’‛]/g, "'").replace(/[“”]/g, '"').replace(/[‐-―−]/g, '-').toLowerCase();
const squash = (s) => norm(s).replace(/\s+/g, '');
const noCommas = (s) => s.replace(/(?<=\d),(?=\d{3}(?!\d))/g, '');

// ---- due words -> a date, resolved against the meeting date (UTC maths, base = "yyyy-MM-dd") -------------
const MONTHS = { jan: 1, feb: 2, mar: 3, apr: 4, may: 5, jun: 6, jul: 7, aug: 8, sep: 9, oct: 10, nov: 11, dec: 12 };
const WD_EN = { mon: 0, tue: 1, wed: 2, thu: 3, fri: 4, sat: 5, sun: 6 };
const WD_JA = { 月: 0, 火: 1, 水: 2, 木: 3, 金: 4, 土: 5, 日: 6 };
const NUM_WORDS = { a: 1, an: 1, one: 1, two: 2, three: 3, four: 4, five: 5, six: 6, seven: 7, eight: 8, nine: 9, ten: 10, twelve: 12 };
const isoDate = (d) => d.toISOString().slice(0, 10);
const addDays = (d, n) => new Date(d.getTime() + n * 86400000);
const monthEnd = (y, m) => new Date(Date.UTC(y, m, 0)); // m = 1..12 -> last day of that month

// Returns "yyyy-MM-dd", or null when the words are not understood. Conventions (written in the template description):
//   "Friday"        = the next Friday after the meeting day      "this Friday" = the Friday of the meeting's week (Mon-Sun)
//   "next Friday"   = the Friday of the following week           "next week"  = that week's Friday
//   "end of week"   = Friday of the meeting's week               "end of month" = the last day of the meeting's month
//   "5/20", "May 20" = the next such date on or after the meeting day; "3/4" is read month/day; "20/10" (first number over 12) is read day/month
function resolveDue(words, base) {
  const w = norm(words).trim();
  if (!w || !/^\d{4}-\d{2}-\d{2}$/.test(base)) return null;
  const [by, bm, bd] = base.split('-').map(Number);
  const b = new Date(Date.UTC(by, bm - 1, bd));
  const monday = addDays(b, -((b.getUTCDay() + 6) % 7));
  let m;
  const future = (mo, da) => { // the next occurrence of month/day on or after the base day
    let d = new Date(Date.UTC(by, mo - 1, da));
    if (d.getUTCMonth() !== mo - 1) return null; // 2/30
    if (d.getTime() < b.getTime()) d = new Date(Date.UTC(by + 1, mo - 1, da));
    return isoDate(d);
  };
  if ((m = w.match(/(\d{4})[\/\-.年](\d{1,2})[\/\-.月](\d{1,2})/))) { const d = new Date(Date.UTC(+m[1], +m[2] - 1, +m[3])); return d.getUTCMonth() === +m[2] - 1 ? isoDate(d) : null; }
  if ((m = w.match(/(\d{1,2})月(\d{1,2})日?/))) return future(+m[1], +m[2]);
  if ((m = w.match(/\b(jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)[a-z]*\.?\s+(\d{1,2})(?:st|nd|rd|th)?\b/))) return future(MONTHS[m[1]], +m[2]);
  if ((m = w.match(/\b(\d{1,2})(?:st|nd|rd|th)?\s+(?:of\s+)?(jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)[a-z]*\b/))) return future(MONTHS[m[2]], +m[1]);
  if ((m = w.match(/\b(\d{1,2})\/(\d{1,2})\b/))) return +m[1] > 12 ? future(+m[2], +m[1]) : future(+m[1], +m[2]);

  // "end of next month" / 来月末, then "end of month" / 月末
  if (/end of (the )?next month|来月末/.test(w)) return isoDate(monthEnd(by, bm + 1));
  if (/end of (the |this )?month|\beom\b|月末|今月中/.test(w)) return isoDate(monthEnd(by, bm));

  // weekday names, with "next" / "this" / week-after-next
  const wdEn = w.match(/\b(mon|tue|wed|thu|fri|sat|sun)[a-z]*\b/);
  const wdJa = w.match(/([月火水木金土日])曜/) ?? w.match(/(?:来週|今週|再来週)の?([月火水木金土日])/);
  if (wdEn && /^(mon|tue|wed|thu|fri|sat|sun)(day|sday|nesday|rsday|urday|s|es|r|rs)?$/.test(wdEn[0]) || wdJa) {
    const idx = wdJa ? WD_JA[wdJa[1]] : WD_EN[wdEn[1]];
    if (/再来週|week after next/.test(w)) return isoDate(addDays(monday, 14 + idx));
    if (/来週|\bnext\b/.test(w)) return isoDate(addDays(monday, 7 + idx));
    if (/今週|\bthis\b/.test(w)) return isoDate(addDays(monday, idx));
    let d = addDays(monday, idx);
    if (d.getTime() <= b.getTime()) d = addDays(d, 7);
    return isoDate(d);
  }

  if (/再来週|week after next/.test(w)) return isoDate(addDays(monday, 14 + 4));
  if (/来週|\bnext week\b/.test(w)) return isoDate(addDays(monday, 7 + 4));
  if (/今週|\bthis week\b|end of (the )?week|\beow\b/.test(w)) return isoDate(addDays(monday, 4));
  if (/day after tomorrow|明後日|あさって/.test(w)) return isoDate(addDays(b, 2));
  if (/tomorrow|明日|あした/.test(w)) return isoDate(addDays(b, 1));
  if (/today|tonight|\beod\b|end of (the )?day|本日|今日|きょう/.test(w)) return base;
  if ((m = w.match(/(\d+)\s*日後/))) return isoDate(addDays(b, +m[1]));
  if ((m = w.match(/(\d+)\s*週間後/))) return isoDate(addDays(b, 7 * +m[1]));
  if ((m = w.match(/\bin\s+(\d+|a|an|one|two|three|four|five|six|seven|eight|nine|ten|twelve)\s+(day|week)s?\b/))) {
    const n = /^\d+$/.test(m[1]) ? +m[1] : NUM_WORDS[m[1]];
    return isoDate(addDays(b, n * (m[2] === 'week' ? 7 : 1)));
  }
  // a day of the month with no month ("the 20th", "20日まで"): the next such day on or after the meeting day
  if ((m = w.match(/\b(\d{1,2})(?:st|nd|rd|th)\b/) ?? w.match(/(\d{1,2})日/))) {
    const day = +m[1];
    for (const add of [0, 1, 2]) {
      const d = new Date(Date.UTC(by, bm - 1 + add, day));
      if (d.getUTCDate() === day && d.getTime() >= b.getTime()) return isoDate(d);
    }
  }
  return null;
}

// ---- small checks -------------------------------------------------------------------------------
// A quote must be a stretch of the transcript (white space, width and quote marks are ignored) and long enough to prove something.
function checkQuote(quote, src, minChars) {
  const q = squash(quote);
  if (!q) return { problems: ['no quote'], idx: -1 };
  if (q.length < minChars) return { problems: ['the quote is too short to prove anything (under ' + minChars + ' characters)'], idx: -1 };
  const idx = src.indexOf(q);
  if (idx < 0) return { problems: ['the quote is not in the transcript'], idx: -1 };
  return { problems: [], idx, len: q.length };
}

// Every number the AI wrote must be written in the transcript.
function numbersMissing(text, srcNum) {
  const nums = noCommas(nfkc(text)).match(/\d+(?:[.:]\d+)*/g) ?? [];
  return [...new Set(nums)].filter((n) => !srcNum.includes(n));
}

// Which attendees does this owner name point at? exact, a first/last name, or (Japanese) a family name that starts the full name.
function matchAttendees(owner, attendees) {
  const o = squash(owner);
  if (!o) return [];
  const exact = attendees.filter((a) => squash(a) === o);
  if (exact.length) return exact;
  return attendees.filter((a) => {
    const tokens = norm(a).split(/\s+/).filter(Boolean);
    const sq = squash(a);
    return tokens.includes(o) || (o.length >= 2 && !/^[\x00-\x7f]*$/.test(o) && (sq.startsWith(o) || o.startsWith(sq)));
  });
}

const CUES = /\b(i'll|i will|we will|we'll|action items?|to-?do|can you|could you|please (send|share|prepare|review|check|update))\b|お願いします|やります|対応します|担当|宿題/;

// ---- the whole check -------------------------------------------------------------------------------
// raw = the AI's text, m = the prepared meeting { meeting_id, title, meeting_date, attendees[], transcript, min_quote_chars, now }
function buildMinutes(raw, m) {
  const src = squash(m.transcript);
  const srcNum = noCommas(src);
  const minChars = Number(m.min_quote_chars) || 8;
  const attendees = m.attendees ?? [];
  let ai = null;
  try {
    const t = String(raw ?? '').replace(/^\s*```(?:json)?\s*/i, '').replace(/\s*```\s*$/, '').trim();
    const a = t.indexOf('{'), z = t.lastIndexOf('}');
    ai = JSON.parse(a >= 0 && z > a ? t.slice(a, z + 1) : t);
  } catch (e) { ai = null; }

  const minutesProblems = [];
  if (!ai) minutesProblems.push('the AI output could not be read as JSON');
  const summary = String(ai?.summary ?? '').trim();
  if (ai && !summary) minutesProblems.push('the summary is empty');
  for (const n of numbersMissing(summary, srcNum)) minutesProblems.push('number ' + n + ' in the summary is not in the transcript');

  const list = (x) => (Array.isArray(x) ? x.filter((o) => o && typeof o === 'object') : []);
  const items = [];
  const push = (type, prefix, o, text, extra, problems, quoteIdx) => {
    const n = items.filter((i) => i.type === type).length + 1;
    items.push({ item_id: m.meeting_id + '-' + prefix + n, meeting_id: m.meeting_id, meeting_date: m.meeting_date, meeting_title: m.title,
      type, text, owner: '', due_text: '', due_date: '', quote: String(o?.quote ?? '').trim(), ...extra,
      status: problems.length ? 'Needs review' : 'OK', problems: problems.join('; ') });
  };
  const baseChecks = (o, text) => {
    const problems = [];
    if (!text) problems.push('the text is empty');
    const q = checkQuote(o.quote, src, minChars);
    problems.push(...q.problems);
    for (const n of numbersMissing(text, srcNum)) problems.push('number ' + n + ' is not in the transcript');
    return { problems, idx: q.idx, len: q.len ?? 0 };
  };

  for (const o of list(ai?.decisions)) {
    const text = String(o.text ?? '').trim();
    push('decision', 'D', o, text, {}, baseChecks(o, text).problems);
  }
  for (const o of list(ai?.open_questions)) {
    const text = String(o.text ?? '').trim();
    push('question', 'Q', o, text, {}, baseChecks(o, text).problems);
  }
  for (const o of list(ai?.action_items)) {
    const text = String(o.task ?? '').trim();
    const c = baseChecks(o, text);
    const problems = c.problems;
    const ownerIn = String(o.owner ?? '').trim();
    let owner = ownerIn || 'Unassigned';
    if (!ownerIn) problems.push('no owner is named');
    else {
      const hit = matchAttendees(ownerIn, attendees);
      if (hit.length === 1) owner = hit[0];
      else if (hit.length > 1) problems.push('owner "' + ownerIn + '" could be more than one attendee');
      else if (!src.includes(squash(ownerIn))) problems.push('owner "' + ownerIn + '" is not an attendee and is not in the transcript');
      else problems.push('owner "' + ownerIn + '" is not in the attendee list');
      // weak check against the classic mistake (the task goes to the wrong person): the name should be near the quote
      if (c.idx >= 0) {
        const win = src.slice(Math.max(0, c.idx - 250), c.idx + c.len + 250);
        const needles = [squash(ownerIn), squash(owner), ...norm(owner).split(/\s+/).map(squash)].filter((s) => s.length >= 2);
        if (!needles.some((s) => win.includes(s))) problems.push('the name "' + ownerIn + '" does not appear near the quote');
      }
    }
    const dueText = String(o.due_text ?? '').trim();
    let dueDate = '';
    if (dueText) {
      if (!src.includes(squash(dueText))) problems.push('the due words "' + dueText + '" are not in the transcript (no date set)');
      else {
        dueDate = resolveDue(dueText, m.meeting_date) ?? '';
        if (!dueDate) problems.push('the due words "' + dueText + '" are not understood (no date set)');
      }
    }
    push('action', 'A', o, text, { owner, due_text: dueText, due_date: dueDate }, problems);
  }

  if (ai && !items.some((i) => i.type === 'action') && CUES.test(norm(m.transcript)))
    minutesProblems.push('the transcript looks like it contains tasks (for example "I\'ll ..."), but no action item was extracted');
  if (!items.length) {
    items.push({ item_id: m.meeting_id + '-N1', meeting_id: m.meeting_id, meeting_date: m.meeting_date, meeting_title: m.title, type: 'note',
      text: 'No decision, action item or open question was extracted. Read the transcript.', owner: '', due_text: '', due_date: '', quote: '',
      status: 'Needs review', problems: ai ? 'nothing was extracted' : 'the AI output could not be read as JSON' });
  }

  const count = (t) => items.filter((i) => i.type === t).length;
  const flagged = items.filter((i) => i.status !== 'OK');
  const status = flagged.length || minutesProblems.length ? 'Needs review' : 'OK';

  // the Slack message
  const line = (i) => {
    const bits = i.type === 'action' ? (i.owner + ' - ' + i.text + (i.due_date ? ' (due ' + i.due_date + ')' : i.due_text ? ' (' + i.due_text + ')' : '')) : i.text;
    return '• ' + bits + (i.status === 'OK' ? '' : ' :warning:');
  };
  const section = (title, type) => {
    const rows = items.filter((i) => i.type === type);
    if (!rows.length) return '';
    return '\n*' + title + '* (' + rows.length + ')\n' + rows.slice(0, 12).map(line).join('\n') + (rows.length > 12 ? '\n• ... and ' + (rows.length - 12) + ' more (see the Items tab)' : '');
  };
  const head = '*Minutes: ' + m.title + '* (' + m.meeting_date + ') - ' +
    (status === 'OK' ? 'all checks passed' : flagged.length + ' item(s) need review' + (minutesProblems.length ? ' + a problem with the minutes' : ''));
  const slack = [head, summary, section('Decisions', 'decision'), section('Action items', 'action'), section('Open questions', 'question'),
    minutesProblems.length ? '\n:warning: ' + minutesProblems.join('; ') : '',
    status === 'OK' ? '' : '\n_:warning: = failed a check. Details are in the Items tab._'].filter(Boolean).join('\n');

  return { meeting_id: m.meeting_id, meeting_date: m.meeting_date, title: m.title, attendees: attendees.join(', '), summary,
    decisions: count('decision'), actions: count('action'), open_questions: count('question'), needs_review: flagged.length, status,
    problems: minutesProblems.join('; '), minuted_at: m.now, items, slack_text: slack };
}

const m = $('Check for duplicates').first().json;
const raw = $input.first().json.content?.[0]?.text ?? $input.first().json.text;
// Claude has no JSON mode, so it may wrap the JSON in a code fence: buildMinutes strips it.
return [{ json: buildMinutes(raw, m) }];

// Only the Minutes fields (the items go to their own tab). Written last: a meeting is "done" only when this row exists.
const { items, slack_text, ...row } = $('Check minutes').first().json;
return [{ json: row }];
